// Connexion – contrôle de la forme des identifiants. L'identifiant est un nom de compte (minuscules, chiffres, . _ -), le code PIN a 4 à 8 chiffres.
const b = $input.first().json?.body ?? {};
const identifiant = String(b.identifiant ?? '').trim().toLowerCase();
const pin = String(b.pin ?? '');
const forme = /^[a-z0-9._-]{2,40}$/.test(identifiant) && /^\d{4,8}$/.test(pin);
return [{ json: { identifiant: forme ? identifiant : 'format-invalide', pin: forme ? pin : '', forme } }];

// Connexion – vérification du PIN : scrypt (haché avec un sel propre à chaque soignant), comparaison à temps constant.
// Un identifiant inconnu fait le même calcul que s'il existait : la durée ne révèle pas si le compte existe.
const crypto = require('crypto');
const demande = $('Contrôler la connexion').first().json;
const s = $input.first().json ?? {};
const FAUX = 'scrypt$00000000000000000000000000000000$' + '00'.repeat(32);
const [, sel, attendu] = String(s.pin_hash && s.actif ? s.pin_hash : FAUX).split('$');
const calcule = crypto.scryptSync(demande.pin, Buffer.from(sel, 'hex'), 32);
const bon = crypto.timingSafeEqual(calcule, Buffer.from(attendu, 'hex'));
const existe = Boolean(s.identifiant && s.actif && s.pin_hash);
let motif = 'ok';
if (!demande.forme) motif = 'format';
else if (!existe || !bon) motif = 'identifiants';
else if (s.verrouille) motif = 'verrouille'; // même avec le bon PIN : compte verrouillé 5 minutes après 5 échecs
return [{ json: { autorise: motif === 'ok', motif, identifiant: demande.identifiant, nom: motif === 'ok' ? s.nom : null } }];

// Connexion – jeton de session : 32 octets aléatoires (43 caractères). Il n'est renvoyé qu'une fois ; la base ne garde que son SHA-256.
const crypto = require('crypto');
const v = $('Vérifier le PIN').first().json;
const jeton = crypto.randomBytes(32).toString('base64url');
return [{ json: { jeton, hash: crypto.createHash('sha256').update(jeton).digest('hex'), identifiant: v.identifiant, nom: v.nom } }];

// Connexion – réponse : jeton, soignant et fin de validité de la session.
const j = $('Créer le jeton').first().json;
const s = $input.first().json ?? {};
return [{ json: { jeton: j.jeton, soignant: { identifiant: j.identifiant, nom: j.nom }, expire_le: s.expire_le } }];

// Connexion – refus : un message identique pour un mauvais identifiant et un mauvais PIN ; seul le verrouillage est signalé.
const v = $('Vérifier le PIN').first().json;
return [{ json: { erreur: v.motif === 'verrouille' ? 'verrouille' : 'identifiants' } }];
